            throw BusinessException.unprocessable("WINDOW_EXPIRED", "授粉窗口已过期");
        }
        PollenBatch batch = pollenBatches.findByBatchNo(request.pollenBatchNo())
                .orElseThrow(() -> BusinessException.unprocessable("POLLEN_BATCH_UNKNOWN", "花粉批号未登记"));
